##
# Expected state info generated by transforming the bison output for
# the specified grammar.
#
# To match the output with ids in it we generate a regex from the
# desired output.
#
# The issue however is that we are using a lot of regex special
# characters, so we have to escape the string then insert the id
# matcher.
EXPECTED_PARSER = Regexp.escape(<<PARSER) % { oid: /\S+/ }
Lr0 %<oid>s
  @tokens = BiHash { %<oid>s
    "$" <=> 1,
    "*" <=> 2,
    "+" <=> 3,
    "0" <=> 4,
    "1" <=> 5,
    :$accept <=> 6,
    :S <=> 7,
    :E <=> 8,
    :B <=> 9
  }
  States
    state 0
      [ :$accept -> . :S "$" ] shift :S to 3
      [ :S -> . :E ] shift :E to 4
      [ :E -> . :E "*" :B ] shift :E to 4
      [ :E -> . :E "+" :B ] shift :E to 4
      [ :E -> . :B ] shift :B to 5
      [ :B -> . "0" ] shift "0" to 1
      [ :B -> . "1" ] shift "1" to 2

    state 1
      [ :B -> "0" . ] reduce with 5

    state 2
      [ :B -> "1" . ] reduce with 6

    state 3
      [ :$accept -> :S . "$" ] shift "$" to 6

    state 4
      [ :S -> :E . ] reduce with 1
      [ :E -> :E . "*" :B ] shift "*" to 7
      [ :E -> :E . "+" :B ] shift "+" to 8

    state 5
      [ :E -> :B . ] reduce with 4

    state 6
      [ :$accept -> :S "$" . ] accept

    state 7
      [ :E -> :E "*" . :B ] shift :B to 9
      [ :B -> . "0" ] shift "0" to 1
      [ :B -> . "1" ] shift "1" to 2

    state 8
      [ :E -> :E "+" . :B ] shift :B to 10
      [ :B -> . "0" ] shift "0" to 1
      [ :B -> . "1" ] shift "1" to 2

    state 9
      [ :E -> :E "*" :B . ] reduce with 2

    state 10
      [ :E -> :E "+" :B . ] reduce with 3
  end
end
PARSER

EXPECTED_PARSER_REGEX = Regexp.compile(EXPECTED_PARSER)

RSpec.describe LrExamples::Lr0 do
  subject(:parser) { described_class.new(grammar) }

  context 'with Grammar 3' do
    let(:grammar) { Grammars::G3 }

    it 'computes the parser states' do
      io = StringIO.new
      rp(parser, output: io, color: false)
      expect(io.string).to match(EXPECTED_PARSER_REGEX)
    end
  end

  context 'with Grammar 4' do
    let(:grammar) { Grammars::G4 }

    it 'computes the nullable tokens' do
      token_ids = parser.nullable_tokens

      tokens = token_ids.map do |id|
        parser.tokens.inverted[id]
      end.to_set

      expect(tokens).to eq(Set[:F, :C, :D])
    end
  end
end
